// ?releaseWeaponLock@WeaponSet@@QAEXW4WeaponLockType@@@Z
// partial score=0.92 date=2026-09-07
// ?releaseWeaponLock@WeaponSet@@QAEXW4WeaponLockType@@@Z
// Retail 0x001EBB40.  The BFME body clears the lock and the three model
// condition bits that the weapon lock sets while the attack runs.

enum WeaponLockType
{
    NOT_LOCKED = 0,
    LOCKED_TEMPORARILY = 1,
    LOCKED_PERMANENTLY = 2
};

class Object;

class GameLogic
{
public:
    Object *findObjectByID( int id );
};

extern GameLogic *TheGameLogic;

template <int NUMBITS>
class BitFlags
{
public:
    enum BogusInitType
    {
        kInit = 0
    };

    BitFlags( BogusInitType, int index1, int index2, int index3 );

private:
    unsigned int m_words[ (NUMBITS + 31) / 32 ];
};

typedef BitFlags<304> ModelConditionFlags;

class Object
{
public:
    void clearModelConditionFlags( const ModelConditionFlags &flags );
};

class WeaponSet
{
public:
    void releaseWeaponLock( WeaponLockType lockType );

private:
    char m_pad_00[ 0x1c ];
    WeaponLockType m_curWeaponLockedStatus;
    char m_pad_20[ 0x34 - 0x20 ];
    int m_objectId;
};

void WeaponSet::releaseWeaponLock( WeaponLockType lockType )
{
    Object *object = TheGameLogic->findObjectByID( m_objectId );
    WeaponLockType currentLock = m_curWeaponLockedStatus;
    int none = 0;
    if( currentLock == (WeaponLockType)none )
        return;

    if( lockType != LOCKED_PERMANENTLY )
    {
        if( lockType != LOCKED_TEMPORARILY )
            return;
        if( currentLock != lockType )
            return;
    }

    if( object == (Object *)none )
    {
        m_curWeaponLockedStatus = (WeaponLockType)none;
        return;
    }

    m_curWeaponLockedStatus = (WeaponLockType)none;
    object->clearModelConditionFlags(
        ModelConditionFlags( ModelConditionFlags::kInit, 0x88, 0x89, 0x8A ) );
}
